import * as React from "react";

export function StrokeText({ text = "OPENUI", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [progress, setProgress] = React.useState(0);
  React.useEffect(() => {
    let p = 0;
    const id = setInterval(() => { p += 2; setProgress(Math.min(p, 100)); if (p >= 100) clearInterval(id); }, 16);
    return () => clearInterval(id);
  }, [text]);
  return (
    <div className={`relative select-none ${className}`}>
      <svg viewBox="0 0 400 100" className="w-full">
        <text x="50%" y="75" textAnchor="middle" fontFamily="monospace" fontSize="72" fontWeight="900"
          fill="none" stroke="currentColor" strokeWidth="2" strokeDasharray="1000" strokeDashoffset={1000 - progress * 10}
          style={{ transition: "stroke-dashoffset 0.05s linear" }} className="text-oxide">
          {text}
        </text>
      </svg>
    </div>
  );
}

import * as React from "react";
import { StrokeText } from "./stroke-text";

export default function StrokeTextDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <StrokeText
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
